local f=OWH.owner; if not f then DEFAULT_CHAT_FRAME:AddMessage("PROBE2 owner=nil") else local n="?"; if f.GetName then n=tostring(f:GetName()) end; local e=f.GetScript and (f:GetScript("OnEnter")~=nil) or false; local l=f.GetScript and (f:GetScript("OnLeave")~=nil) or false; local u=f.GetScript and (f:GetScript("OnUpdate")~=nil) or false; local ut=(f.UpdateTooltip~=nil); DEFAULT_CHAT_FRAME:AddMessage("PROBE2 "..n.." OnEnter="..tostring(e).." OnLeave="..tostring(l).." OnUpdate="..tostring(u).." UpdateTooltip="..tostring(ut)) end